import{z as o,x as n,o as B,c as s,q as A,j as l,D as a,d as t,s as i,S as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"KV 的生命周期与所有权","description":"","frontmatter":{"title":"KV 的生命周期与所有权","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kv-lifecycle-ownership.md","filePath":"llm/kv-lifecycle-ownership.md","lastUpdated":1791063341000}'),p={name:"llm/kv-lifecycle-ownership.md"};function d(C,E,m,h,D,c){const e=n("Mermaid");return B(),s("div",null,[E[2]||(E[2]=A('<h1 id="kv-的生命周期与所有权" tabindex="-1">KV 的生命周期与所有权 <a class="header-anchor" href="#kv-的生命周期与所有权" aria-label="Permalink to &quot;KV 的生命周期与所有权&quot;">​</a></h1><div class="epigraph"><p>页表回答「放在哪」，生命周期回答「归谁、活多久」；所有权不定，共享和释放迟早写坏别人的字节。</p><footer>—— 据 Kwon et al., PagedAttention, SOSP 2023 的块表与引用计数整理</footer></div><p><a href="/llm/ak-map">上一课</a>把内核工程收进五条坐标与一条交付链：tile 怎么切、变体差在头与地址、快来自字节不过 HBM，且接口比内核活得久——页表与变长都写进了接口合同。本课程顺着「地址」这条坐标往下走：KV 在请求之间被写入、追加、共享、搬移、释放，谁有权写哪一页、页何时归还——所有权错了，再快的核也在算被污染的缓存。本课立起地基：生命周期与所有权。寻址与 gather 不重讲；后课的分页、共享、压缩默认这套状态机已经成立。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把 KV 当成「随张量来的私有缓冲」，生命周期就散落在代码各处：预填充写入一次，解码每步追加，束搜索与并行采样复制，请求结束释放。所有权含糊出两类错。写冲突：并行采样共享同一前缀页，却有实现路径就地更新——另一个请求的注意力会读到被改写的键，错误延迟数百步才浮现，极难归因。悬空引用：请求结束把页还池，异步的投机校验、续跑中的请求、或跨机传输的接收端还握着旧块表，读到的页已被下一请求覆写。两类错的共同根源是没有回答：这一页此刻归谁、处于什么状态。</p>',5)),(B(),l(r,null,{default:a(()=>[i(e,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%B9%B6%E8%A1%8C%E9%87%87%E6%A0%B7%E5%85%B1%E4%BA%AB%E5%90%8C%E4%B8%80%E5%89%8D%E7%BC%80%E9%A1%B5%22%5D%20--%3E%20W%5B%22%E5%AE%9E%E7%8E%B0%E8%B7%AF%E5%BE%84%E5%B0%B1%E5%9C%B0%E6%9B%B4%E6%96%B0%E4%BA%86%E5%85%B1%E4%BA%AB%E9%A1%B5%22%5D%0A%20%20W%20--%3E%20W2%5B%22%E5%8F%A6%E4%B8%80%E4%B8%AA%E8%AF%B7%E6%B1%82%E7%9A%84%E6%B3%A8%E6%84%8F%E5%8A%9B%E8%AF%BB%E5%88%B0%E8%A2%AB%E6%94%B9%E5%86%99%E7%9A%84%E9%94%AE%22%5D%0A%20%20W2%20--%3E%20W3%5B%22%E9%94%99%E8%AF%AF%E5%BB%B6%E8%BF%9F%E6%95%B0%E7%99%BE%E6%AD%A5%E6%89%8D%E6%B5%AE%E7%8E%B0%2C%20%E6%9E%81%E9%9A%BE%E5%BD%92%E5%9B%A0%22%5D%0A%20%20R%5B%22%E8%AF%B7%E6%B1%82%E7%BB%93%E6%9D%9F%2C%20%E9%A1%B5%E5%BD%92%E8%BF%98%E6%B1%A0%E5%AD%90%22%5D%20--%3E%20A%5B%22%E5%BC%82%E6%AD%A5%E6%A0%A1%E9%AA%8C%E6%88%96%E8%B7%A8%E6%9C%BA%E6%8E%A5%E6%94%B6%E7%AB%AF%E8%BF%98%E6%8F%A1%E7%9D%80%E6%97%A7%E5%9D%97%E8%A1%A8%22%5D%0A%20%20A%20--%3E%20A2%5B%22%E8%AF%BB%E5%88%B0%E7%9A%84%E9%A1%B5%E5%B7%B2%E8%A2%AB%E4%B8%8B%E4%B8%80%E8%AF%B7%E6%B1%82%E8%A6%86%E5%86%99%3A%20%E6%82%AC%E7%A9%BA%E5%BC%95%E7%94%A8%22%5D%0A%20%20W3%20--%3E%20F%5B%22%E5%85%B1%E5%90%8C%E6%A0%B9%E6%BA%90%3A%20%E6%B2%A1%E5%9B%9E%E7%AD%94%E8%BF%99%E4%B8%80%E9%A1%B5%E6%AD%A4%E5%88%BB%E5%BD%92%E8%B0%81%22%5D%0A%20%20A2%20--%3E%20F%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<p>大小本身是<a href="/llm/kv-cache-size-math">算得清的</a>：\\(\\mathrm{KV}=2Ln h_{kv} d b\\) 随长度与并发线性涨，<a href="/llm/paged-attention">分页</a>把这段字节切成池里的页。本课的问题不在公式，而在簿记：页从池里出来的那一刻起，发生了什么。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把每条 KV 页钉成状态机，所有权跟着状态走。</p><ul><li><strong>空闲</strong>：在池里，不属于任何人。</li><li><strong>独占</strong>：被恰好一个请求的块表引用，预填充写入、解码追加都发生在这里；唯一的可写状态。</li><li><strong>共享</strong>：前缀命中后引用计数大于 1，全员只读；分叉要写，先写时复制到新页。</li><li><strong>离场</strong>：被换出（<a href="/llm/kv-offload">卸载</a>）或在传输路上；块表标注去向，回来或作废都走显式路径。</li></ul><p>规则三条。写权只属于唯一引用者：引用计数大于 1 时任何写入先复制。释放由最后一个引用消失触发，无论请求结束、会话过期还是缓存逐出。块表是唯一真相源：投机回滚、抢占恢复、迁移失败，都要先改块表再动内存，顺序反了就是悬空引用。生成开始前定新增 KV 的归属：并行采样各分叉拿各的新页，祖先页只读——<a href="/llm/vllm-paged">vLLM</a> 的 copy-on-write 契约。</p><p><span class="marginnote">直觉类比：copy-on-write 像合租室友共用一本公共笔记——人人都能看，谁想改，先去复印一份再改自己的，原件永远保持原样。没有这条规矩，第一个乱改的人会悄悄污染所有室友的答案，而且没人知道是哪天改坏的。</span></p>',6)),(B(),l(r,null,{default:a(()=>[i(e,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20FREE%5B%22%E7%A9%BA%E9%97%B2%EF%BC%9A%E5%9C%A8%E9%A1%B5%E6%B1%A0%22%5D%20--%3E%20OWN%5B%22%E7%8B%AC%E5%8D%A0%EF%BC%9Aprefill%20%E5%86%99%E5%85%A5%20%2F%20decode%20%E8%BF%BD%E5%8A%A0%22%5D%0A%20%20OWN%20--%3E%7C%22%E5%89%8D%E7%BC%80%E5%91%BD%E4%B8%AD%EF%BC%8C%E8%AE%A1%E6%95%B0%E5%8A%A0%E4%B8%80%22%7C%20SHARE%5B%22%E5%85%B1%E4%BA%AB%EF%BC%9A%E5%8F%AA%E8%AF%BB%22%5D%0A%20%20SHARE%20--%3E%7C%22%E5%88%86%E5%8F%89%E8%AF%B7%E6%B1%82%E8%A6%81%E5%86%99%22%7C%20COW%5B%22%E5%A4%8D%E5%88%B6%E5%88%B0%E6%96%B0%E9%A1%B5%EF%BC%8C%E5%9B%9E%E5%88%B0%E7%8B%AC%E5%8D%A0%22%5D%0A%20%20COW%20--%3E%20OWN%0A%20%20SHARE%20--%3E%7C%22%E5%85%A8%E9%83%A8%E5%BC%95%E7%94%A8%E7%BB%93%E6%9D%9F%22%7C%20FREE%0A%20%20OWN%20--%3E%7C%22%E8%AF%B7%E6%B1%82%E7%BB%93%E6%9D%9F%22%7C%20FREE%0A%20%20OWN%20--%3E%7C%22%E6%8D%A2%E5%87%BA%20%2F%20%E8%BF%81%E7%A7%BB%22%7C%20GONE%5B%22%E7%A6%BB%E5%9C%BA%EF%BC%9A%E5%9D%97%E8%A1%A8%E6%A0%87%E6%B3%A8%E5%8E%BB%E5%90%91%22%5D%0A%20%20GONE%20--%3E%7C%22%E6%81%A2%E5%A4%8D%22%7C%20OWN%0A%20%20GONE%20--%3E%7C%22%E4%BD%9C%E5%BA%9F%22%7C%20FREE%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>所有权先行，是因为引用计数是后面所有课的共同底座。<a href="/llm/prefix-caching">前缀共享</a>用它表达「一份物理页、多个逻辑用户」；驱逐用它区分「缓存页」与「活跃页」——缓存页无活跃请求也不回收，活跃页连缓存逐出都不许；<a href="/llm/pd-kv-transfer">迁移</a>用它保证传输期间源端不写。三个场景共用一台状态机；各写一套私有标记，一定在边角对不上。</p><p><span class="marginnote">直觉类比：块表是这块内存唯一的「户口本」——投机回滚、迁移失败都要先改户口再动人。户口上写的地址和实际住着的人对不上的那段时间，就是悬空引用发生的地方；所以规则是先改表、后动内存，让窗口等于零。</span></p><p>边界事件最常漏。抢占把独占页换成「被换出」，恢复时块表没跟着走，换出页就成了无人认领的垃圾；取消与超时要连共享引用一起减，否则前缀缓存里挂着已死会话的页。本课程后课的碎片率、命中率、成本分摊，全部定义在这台状态机上——状态含糊，数字就对不上。</p><p><span class="marginnote">Llama-3-8B（32 层、8 个 KV 头、头维 128、FP16）每 token 的 KV 是 128 KiB，一个 4K token 的会话占 512 MiB。若这段前缀被 3 个请求共享，物理 in-use 是 512 MiB，逻辑占用是 1.5 GiB——所有权簿记不同，两种说法都对，也都能骗人。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>状态机不等于线程安全：同一页内的并发追加还要锁或原子操作，所有权只保证「没有两个写者」。它也不管页内字节怎么排——那是 <a href="/llm/kv-layout">布局</a> 的事。引擎的持有粒度不同：按请求、按块、或按前缀树节点记引用；跨引擎迁移时引用计数不可移植，只能传页清单，在对端重建。把生命周期写成请求对象的生命周期是常见偷懒：请求被抢占、迁移、续跑时它就失效了，所有权必须挂在块上。</p><p><span class="marginnote">常见误区：把生命周期挂在「请求对象」上看似省事，但请求会被抢占、取消、续跑——对象没了，它占的页还活着；反过来对象还在，页可能已被共享冻结。所有权必须挂在物理块上，因为块活得比任何一次请求都久。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>生命周期：空闲 → 独占（唯一可写）→ 共享（只读）→ 离场 → 空闲，所有权随状态走。</li><li>三条规则：写权只属唯一引用者、共享写前复制、释放由最后一个引用触发。</li><li>块表是唯一真相源；异步路径先改表再动内存。</li><li>引用计数是共享、驱逐、迁移、测量的公共底座，不是子系统私有细节。</li><li>所有权挂在块上而非请求对象上；抢占与取消连共享引用一起结账。</li><li>出处：Kwon et al., PagedAttention, SOSP 2023（块表、引用计数与 copy-on-write）；大小口径见 Pope et al., 2022。据本仓库既有课程整理，不发明新文献。</li></ul>',10))])}const f=o(p,[["render",d]]);export{_ as __pageData,f as default};
